  main(()->{View root=activity.choiceDialog.getWindow().getDecorView();check(root.findViewWithTag("coffee_restore")!=null&&root.findViewWithTag("coffee_hide_offer")!=null,"restore and do-not-show controls exist");root.findViewWithTag("coffee_buy").performClick();check(coffee.unlocked()&&coffee.level(10)==10&&v.adCard==null,"simulated buy removes real ad child and unlocks strongest AI");});screenshot("51_coffee_purchased.png");clickDialog("閉じる");
