  main(()->{coffee.debugGrant(false);activity.showCoffee();});awaitChoice("閉じる");main(()->activity.choiceDialog.getWindow().getDecorView().findViewWithTag("coffee_restore").performClick());main(()->check(coffee.unlocked()&&v.adCard==null,"restore reapplies both benefits"));clickDialog("閉じる");main(()->{coffee.fixture=false;coffee.debugGrant(null);coffee.promptPending=false;coffee.hideOffer(true);});
  try(PrintWriter out=new PrintWriter(new File(getTargetContext().getExternalFilesDir(null),"coffee_purchase.txt"))){out.println("PASS RSA receipt signature/product/state checks; cancel/pending fail closed; first/second foreground and hide persistence; settings offer/restore controls; simulated purchase/restore removes ads including archive/footer and unlocks level 10. Google Play product is unregistered: no real Play purchase, acknowledgement, charge or console restoration was tested.");}
